/**
 * ============================================================================
 *  custom_weapons.inc - Non-ID Modular Custom Weapon Synchronization
 * ============================================================================
 *  Target: SA-MP / open.mp Server with Pawn.RakNet
 * ============================================================================
 */

#if !defined _samp_included
    #include <a_samp>
#endif
#if !defined PAWNRAKNET_INC_
    #include <Pawn.RakNet>
#endif

#define WEAPON_RPC_ID   (239)

#if !defined g_PlayerWeaponModel
new g_PlayerWeaponModel[MAX_PLAYERS][47][32];
#endif

stock SetPlayerWeaponModel(playerid, weaponid, const modelName[])
{
    if (playerid < 0 || playerid >= MAX_PLAYERS) return 0;
    if (weaponid < 1 || weaponid > 46) return 0;

    format(g_PlayerWeaponModel[playerid][weaponid], 32, "%s", modelName);

    new payload[64];
    format(payload, sizeof(payload), "%d %d %s", playerid, weaponid, modelName);

    new BitStream:bs = BS_New();
    BS_WriteString(bs, payload);

    for (new i = 0; i < MAX_PLAYERS; i++)
    {
        if (IsPlayerConnected(i))
        {
            PR_SendRPC(bs, i, WEAPON_RPC_ID, PR_HIGH_PRIORITY, PR_RELIABLE_ORDERED);
        }
    }
    BS_Delete(bs);
    return 1;
}

stock ResetPlayerWeaponModel(playerid, weaponid)
{
    return SetPlayerWeaponModel(playerid, weaponid, "none");
}

stock SyncPlayerWeaponsToPlayer(playerid, targetid)
{
    if (!IsPlayerConnected(playerid) || !IsPlayerConnected(targetid)) return 0;

    for (new w = 1; w <= 46; w++)
    {
        if (g_PlayerWeaponModel[playerid][w][0] != '\0' && strcmp(g_PlayerWeaponModel[playerid][w], "none", true) != 0)
        {
            new payload[64];
            format(payload, sizeof(payload), "%d %d %s", playerid, w, g_PlayerWeaponModel[playerid][w]);

            new BitStream:bs = BS_New();
            BS_WriteString(bs, payload);
            PR_SendRPC(bs, targetid, WEAPON_RPC_ID, PR_HIGH_PRIORITY, PR_RELIABLE_ORDERED);
            BS_Delete(bs);
        }
    }
    return 1;
}

