#endif
#define _DISCORD_AUTH_INC_

/**
 * ============================================================================
 *  discord_auth.inc - Modular Discord Authentication for SA-MP / open.mp & CEF
 * ============================================================================
 *  Target: open.mp server with CEF plugin
 *  Authors: Core Development Team (WIP Roleplay)
 * ============================================================================
 */

#if !defined _samp_included
    #include <a_samp>
#endif
#if !defined _INC_omp_http && !defined _http_included
    #include <omp_http>
#endif
#if !defined CEFSAMP_INC_
    #include <cef>
#endif

// ── Configuration Constants ──
#if !defined DISCORD_BROWSER_ID
    #define DISCORD_BROWSER_ID          (180)
#endif
#if !defined DISCORD_AUTH_URL
    #define DISCORD_AUTH_URL            "discord_login.html"
#endif
#if !defined DISCORD_GATEWAY_HOST
    #define DISCORD_GATEWAY_HOST        "127.0.0.1:8088"
#endif
#if !defined DISCORD_CHECK_INTERVAL_MS
    #define DISCORD_CHECK_INTERVAL_MS   (2000)
#endif

// ── Per-Player State ──
new g_PlayerDiscordCode[MAX_PLAYERS][16];
new g_PlayerDiscordId[MAX_PLAYERS][32];
new g_PlayerDiscordTag[MAX_PLAYERS][64];
new g_PlayerDiscordAvatar[MAX_PLAYERS][128];
new g_PlayerDiscordRole[MAX_PLAYERS][32];
new bool:g_PlayerIsDiscordAuth[MAX_PLAYERS];
new g_DiscordCheckTimer[MAX_PLAYERS] = {-1, ...};

// ── Forward Declarations ──
forward OnDiscordSessionResponse(index, responseCode, const data[]);
forward OnDiscordPollResponse(index, responseCode, const data[]);
forward Discord_PollStatus(playerid);
forward Discord_FinishLogin(playerid);
forward OnDiscordReadyCEF(player_id, const arguments[]);
forward OnPlayerDiscordAuth(playerid, const discord_id[], const discord_tag[]);

// ── Lightweight JSON String Extractor (Whitespace-tolerant) ──
stock ExtractJsonValue(const json[], const key[], output[], maxlen = sizeof(output))
{
    output[0] = '\0';
    new needle[64];
    format(needle, sizeof(needle), "\"%s\"", key);
    new pos = strfind(json, needle, false);
    if (pos == -1) return 0;

    pos += strlen(needle);
    // Lewati spasi/tab sebelum titik dua
    while (json[pos] && (json[pos] == ' ' || json[pos] == '\t')) pos++;
    if (json[pos] != ':') return 0;
    pos++; // lewati ':'

    // Lewati spasi/tab setelah titik dua
    while (json[pos] && (json[pos] == ' ' || json[pos] == '\t')) pos++;

    if (json[pos] == '\"')
    {
        pos++; // lewati tanda kutip pembuka
        new end_pos = strfind(json, "\"", false, pos);
        if (end_pos != -1)
        {
            strmid(output, json, pos, end_pos, maxlen);
            return 1;
        }
    }
    else
    {
        new end_pos = pos;
        while (json[end_pos] && json[end_pos] != ',' && json[end_pos] != '}' && json[end_pos] != ' ' && json[end_pos] != '\r' && json[end_pos] != '\n')
        {
            end_pos++;
        }
        if (end_pos > pos)
        {
            strmid(output, json, pos, end_pos, maxlen);
            return 1;
        }
    }
    return 0;
}

// ── Initialize Discord Auth Subscriptions ──
stock DiscordAuth_Init()
{
    cef_subscribe("discord:ready", "OnDiscordReadyCEF");
    cef_subscribe("discord:close", "OnDiscordCloseCEF");
    printf("[Discord Auth] Initialized. Gateway host: %s, Browser ID: %d", DISCORD_GATEWAY_HOST, DISCORD_BROWSER_ID);
    return 1;
}

// ── Close Callback from CEF ──
forward OnDiscordCloseCEF(player_id, const arguments[]);
public OnDiscordCloseCEF(player_id, const arguments[])
{
    if (!IsPlayerConnected(player_id)) return 1;
    cef_focus_browser(player_id, DISCORD_BROWSER_ID, false);
    cef_destroy_browser(player_id, DISCORD_BROWSER_ID);
    TogglePlayerControllable(player_id, true);
    if (g_DiscordCheckTimer[player_id] != -1)
    {
        KillTimer(g_DiscordCheckTimer[player_id]);
        g_DiscordCheckTimer[player_id] = -1;
    }
    printf("[Discord Auth] Player %d closed the Discord login interface.", player_id);
    return 1;
}

// ── Trigger Show Discord Login ──
stock ShowDiscordAuth(playerid)
{
    if (!IsPlayerConnected(playerid)) return 0;

    // Reset player state
    g_PlayerDiscordCode[playerid][0] = '\0';
    g_PlayerDiscordId[playerid][0] = '\0';
    g_PlayerDiscordTag[playerid][0] = '\0';
    g_PlayerDiscordAvatar[playerid][0] = '\0';
    g_PlayerIsDiscordAuth[playerid] = false;

    if (g_DiscordCheckTimer[playerid] != -1)
    {
        KillTimer(g_DiscordCheckTimer[playerid]);
        g_DiscordCheckTimer[playerid] = -1;
    }

    new playerName[MAX_PLAYER_NAME];
    GetPlayerName(playerid, playerName, sizeof(playerName));

    // Freeze player during login
    TogglePlayerControllable(playerid, false);

    // 1. Request Session from Discord Auth Gateway HTTP API
    new postBody[128];
    format(postBody, sizeof(postBody), "{\"player_id\":%d,\"player_name\":\"%s\",\"expires_in\":300}", playerid, playerName);

    new url[128];
    format(url, sizeof(url), "%s/api/auth/session", DISCORD_GATEWAY_HOST);
    HTTP(playerid, HTTP_POST, url, postBody, "OnDiscordSessionResponse");

    // 2. Open CEF Browser
    cef_create_browser(playerid, DISCORD_BROWSER_ID, DISCORD_AUTH_URL, false, true);
    cef_focus_browser(playerid, DISCORD_BROWSER_ID, true);

    printf("[Discord Auth] Opened login browser for player %s (ID: %d)", playerName, playerid);
    return 1;
}

// ── Callback when Gateway responds with session code ──
public OnDiscordSessionResponse(index, responseCode, const data[])
{
    new playerid = index;
    if (!IsPlayerConnected(playerid)) return 1;

    if (responseCode == 200)
    {
        ExtractJsonValue(data, "code", g_PlayerDiscordCode[playerid], sizeof(g_PlayerDiscordCode[]));
        new playerName[MAX_PLAYER_NAME];
        GetPlayerName(playerid, playerName, sizeof(playerName));

        printf("[Discord Auth] Session created for player %d: Code '%s'", playerid, g_PlayerDiscordCode[playerid]);

        // Send Session Code to CEF UI
        cef_emit_event(playerid, "discord:initSession", 
            CEFSTR(g_PlayerDiscordCode[playerid]), 
            CEFINT(300), 
            CEFSTR(playerName));

        // Start polling Gateway for verification status
        if (g_DiscordCheckTimer[playerid] != -1) KillTimer(g_DiscordCheckTimer[playerid]);
        g_DiscordCheckTimer[playerid] = SetTimerEx("Discord_PollStatus", DISCORD_CHECK_INTERVAL_MS, true, "i", playerid);
    }
    else
    {
        printf("[Discord Auth ERROR] Failed to create session on Gateway! HTTP Response: %d", responseCode);
        // Fallback: Send mock code so UI doesn't hang if Gateway is offline
        format(g_PlayerDiscordCode[playerid], sizeof(g_PlayerDiscordCode[]), "DC-OFFLINE");
        cef_emit_event(playerid, "discord:initSession", CEFSTR("DC-OFFLINE"), CEFINT(300), CEFSTR("Offline Mode"));
    }
    return 1;
}

// ── CEF Ready Callback ──
public OnDiscordReadyCEF(player_id, const arguments[])
{
    if (!IsPlayerConnected(player_id)) return 1;
    // Re-sync current code if browser just loaded
    if (g_PlayerDiscordCode[player_id][0] != '\0')
    {
        new playerName[MAX_PLAYER_NAME];
        GetPlayerName(player_id, playerName, sizeof(playerName));
        cef_emit_event(player_id, "discord:initSession", 
            CEFSTR(g_PlayerDiscordCode[player_id]), 
            CEFINT(300), 
            CEFSTR(playerName));
    }
    return 1;
}

// ── Poll Status Timer ──
public Discord_PollStatus(playerid)
{
    if (!IsPlayerConnected(playerid) || g_PlayerIsDiscordAuth[playerid])
    {
        if (g_DiscordCheckTimer[playerid] != -1)
        {
            KillTimer(g_DiscordCheckTimer[playerid]);
            g_DiscordCheckTimer[playerid] = -1;
        }
        return 1;
    }

    if (g_PlayerDiscordCode[playerid][0] == '\0') return 1;

    new url[128];
    format(url, sizeof(url), "%s/api/auth/status?code=%s", DISCORD_GATEWAY_HOST, g_PlayerDiscordCode[playerid]);
    HTTP(playerid, HTTP_GET, url, "", "OnDiscordPollResponse");
    return 1;
}

// ── Gateway Poll Response Handler ──
public OnDiscordPollResponse(index, responseCode, const data[])
{
    new playerid = index;
    if (!IsPlayerConnected(playerid) || g_PlayerIsDiscordAuth[playerid]) return 1;

    if (responseCode == 200)
    {
        new status[32];
        ExtractJsonValue(data, "status", status, sizeof(status));

        if (!strcmp(status, "AUTHORIZED", true))
        {
            g_PlayerIsDiscordAuth[playerid] = true;
            if (g_DiscordCheckTimer[playerid] != -1)
            {
                KillTimer(g_DiscordCheckTimer[playerid]);
                g_DiscordCheckTimer[playerid] = -1;
            }

            ExtractJsonValue(data, "discord_id", g_PlayerDiscordId[playerid], sizeof(g_PlayerDiscordId[]));
            ExtractJsonValue(data, "discord_tag", g_PlayerDiscordTag[playerid], sizeof(g_PlayerDiscordTag[]));
            ExtractJsonValue(data, "avatar_url", g_PlayerDiscordAvatar[playerid], sizeof(g_PlayerDiscordAvatar[]));
            ExtractJsonValue(data, "discord_role", g_PlayerDiscordRole[playerid], sizeof(g_PlayerDiscordRole[]));
            if (g_PlayerDiscordRole[playerid][0] == '\0') format(g_PlayerDiscordRole[playerid], sizeof(g_PlayerDiscordRole[]), "DEVELOPER");

            printf("[Discord Auth SUCCESS] Player %d linked to Discord %s (ID: %s, Role: %s)", 
                playerid, g_PlayerDiscordTag[playerid], g_PlayerDiscordId[playerid], g_PlayerDiscordRole[playerid]);

            // Notify CEF UI of login success
            cef_emit_event(playerid, "discord:loginSuccess", 
                CEFSTR(g_PlayerDiscordTag[playerid]), 
                CEFSTR(g_PlayerDiscordId[playerid]), 
                CEFSTR(g_PlayerDiscordAvatar[playerid]));

            // Notify In-Game HUD of Discord Profile & Role
            cef_emit_event(playerid, "game:data:discordProfile", 
                CEFSTR(g_PlayerDiscordTag[playerid]), 
                CEFSTR(g_PlayerDiscordId[playerid]), 
                CEFSTR(g_PlayerDiscordAvatar[playerid]),
                CEFSTR(g_PlayerDiscordRole[playerid]));

            // Notify gamemode callback
            CallLocalFunction("OnPlayerDiscordAuth", "iss", playerid, g_PlayerDiscordId[playerid], g_PlayerDiscordTag[playerid]);

            // Auto close browser and unfreeze player after 2 seconds
            SetTimerEx("Discord_FinishLogin", 2000, false, "i", playerid);
        }
    }
    return 1;
}

// ── Finalize Login & Close CEF ──
public Discord_FinishLogin(playerid)
{
    if (!IsPlayerConnected(playerid)) return 1;

    cef_focus_browser(playerid, DISCORD_BROWSER_ID, false);
    cef_destroy_browser(playerid, DISCORD_BROWSER_ID);
    TogglePlayerControllable(playerid, true);

    new msg[144];
    format(msg, sizeof(msg), "{5865F2}[Discord]{FFFFFF} Selamat datang! Akun Anda terverifikasi sebagai {57F287}%s{FFFFFF}.", g_PlayerDiscordTag[playerid]);
    SendClientMessage(playerid, -1, msg);

    printf("[Discord Auth] Player %d finished login and resumed gameplay.", playerid);
    return 1;
}

// ── Clean up on disconnect ──
stock DiscordAuth_OnPlayerDisconnect(playerid)
{
    if (g_DiscordCheckTimer[playerid] != -1)
    {
        KillTimer(g_DiscordCheckTimer[playerid]);
        g_DiscordCheckTimer[playerid] = -1;
    }
    g_PlayerDiscordCode[playerid][0] = '\0';
    g_PlayerDiscordId[playerid][0] = '\0';
    g_PlayerDiscordTag[playerid][0] = '\0';
    g_PlayerDiscordAvatar[playerid][0] = '\0';
    g_PlayerIsDiscordAuth[playerid] = false;
    return 1;
}

