/**
 * ============================================================================
 *  taser.inc - Realistic Cross-Platform Taser System (Im3D Procedural Wires)
 * ============================================================================
 *  Target: SA-MP / open.mp Server with Pawn.RakNet
 *  RPC ID: 237 (RPC_TASER_EVENT)
 * ============================================================================
 */

#if !defined _samp_included
    #include <a_samp>
#endif
#if !defined PAWNRAKNET_INC_
    #include <Pawn.RakNet>
#endif

#define TASER_RPC_ID        (237)
#define TASER_WEAPON_ID     (23)  // Silenced 9mm
#define TASER_DEFAULT_TIME  (4000) // 4 seconds shock stun

enum E_TASER_STATE
{
    bool:taserActive,
    taserShooter,
    taserVictim,
    taserTimer
};

new g_TaserState[MAX_PLAYERS][E_TASER_STATE];

// Forward callback event
forward OnPlayerTased(playerid, issuerid);

// Internal timer callback
forward OnTaserEffectEnd(victimid);
public OnTaserEffectEnd(victimid)
{
    if (!IsPlayerConnected(victimid)) return 0;

    new shooterid = g_TaserState[victimid][taserShooter];
    g_TaserState[victimid][taserActive] = false;
    g_TaserState[victimid][taserTimer] = 0;

    // Restore controls and clear shock twitch animation
    ClearAnimations(victimid, SYNC_ALL);
    TogglePlayerControllable(victimid, true);

    // Broadcast detach to all clients
    new payload[64];
    format(payload, sizeof(payload), "%d %d 0 0", shooterid, victimid);

    new BitStream:bs = BS_New();
    BS_WriteString(bs, payload);
    for (new i = 0; i < MAX_PLAYERS; i++)
    {
        if (IsPlayerConnected(i))
        {
            PR_SendRPC(bs, i, TASER_RPC_ID, PR_HIGH_PRIORITY, PR_RELIABLE_ORDERED);
        }
    }
    BS_Delete(bs);
    return 1;
}

stock Taser_ShootPlayer(shooterid, victimid, duration_ms = TASER_DEFAULT_TIME)
{
    if (!IsPlayerConnected(shooterid) || !IsPlayerConnected(victimid)) return 0;
    if (shooterid == victimid) return 0;

    // If victim already has an active taser effect, kill old timer
    if (g_TaserState[victimid][taserActive] && g_TaserState[victimid][taserTimer] != 0)
    {
        KillTimer(g_TaserState[victimid][taserTimer]);
    }

    g_TaserState[victimid][taserActive] = true;
    g_TaserState[victimid][taserShooter] = shooterid;
    g_TaserState[victimid][taserVictim] = victimid;

    // Apply SA-MP shock twitching collapse animation (CRACK / crckdeth2)
    ApplyAnimation(victimid, "CRACK", "crckdeth2", 4.1, true, false, false, true, duration_ms, SYNC_ALL);
    TogglePlayerControllable(victimid, false); // Lock movement while stunned

    // Set end timer
    g_TaserState[victimid][taserTimer] = SetTimerEx("OnTaserEffectEnd", duration_ms, false, "i", victimid);

    // Call forward callback
    CallLocalFunction("OnPlayerTased", "ii", victimid, shooterid);

    // Broadcast RPC 237 to all clients: "shooterId victimId 1 durationMs"
    new payload[64];
    format(payload, sizeof(payload), "%d %d 1 %d", shooterid, victimid, duration_ms);

    new BitStream:bs = BS_New();
    BS_WriteString(bs, payload);
    for (new i = 0; i < MAX_PLAYERS; i++)
    {
        if (IsPlayerConnected(i))
        {
            PR_SendRPC(bs, i, TASER_RPC_ID, PR_HIGH_PRIORITY, PR_RELIABLE_ORDERED);
        }
    }
    BS_Delete(bs);
    return 1;
}

stock Taser_Stop(shooterid, victimid)
{
    #pragma unused shooterid
    if (IsPlayerConnected(victimid) && g_TaserState[victimid][taserActive])
    {
        if (g_TaserState[victimid][taserTimer] != 0)
        {
            KillTimer(g_TaserState[victimid][taserTimer]);
        }
        OnTaserEffectEnd(victimid);
        return 1;
    }
    return 0;
}

stock bool:IsPlayerTased(playerid)
{
    if (playerid < 0 || playerid >= MAX_PLAYERS) return false;
    return g_TaserState[playerid][taserActive];
}

