// ── Internal RakNet RPC Transmitters ──
stock WR_SendRPC(playerid, rpcId, const message[])
{
    if (playerid < 0 || playerid >= MAX_PLAYERS || !IsPlayerConnected(playerid)) return 0;
    new BitStream:bs = BS_New();
    BS_WriteString(bs, message);
    PR_SendRPC(bs, playerid, rpcId, PR_HIGH_PRIORITY, PR_RELIABLE_ORDERED);
    BS_Delete(bs);
    return 1;
}

stock WR_BroadcastRPC(rpcId, const message[])
{
    new BitStream:bs = BS_New();
    BS_WriteString(bs, message);
    for (new i = 0; i < MAX_PLAYERS; i++)
    {
        if (IsPlayerConnected(i))
        {
            PR_SendRPC(bs, i, rpcId, PR_HIGH_PRIORITY, PR_RELIABLE_ORDERED);
        }
    }
    BS_Delete(bs);
    return 1;
}

// ── Helper: Ekstraksi Token ke-N dari String Berpemisah Spasi ──
stock GetWardrobeToken(const src[], tokenIndex, dest[], destSize)
{
    new len = strlen(src);
    new i = 0, idx = 0;
    while (i < len && idx < tokenIndex)
    {
        while (i < len && src[i] == ' ') i++;
        while (i < len && src[i] != ' ') i++;
        idx++;
    }
    while (i < len && src[i] == ' ') i++;
    new p = 0;
    while (i < len && src[i] != ' ' && p < destSize - 1) dest[p++] = src[i++];
    dest[p] = '\0';
    return p;
}

// ── Helper: Pemetaan Nama Slot Tato ke Index (0..8) ──
static TattooSlotIndex(const slot[])
{
    if (!strcmp(slot, "tat_arm_l_top")) return 0;
    if (!strcmp(slot, "tat_arm_l_btm")) return 1;
    if (!strcmp(slot, "tat_arm_r_top")) return 2;
    if (!strcmp(slot, "tat_arm_r_btm")) return 3;
    if (!strcmp(slot, "tat_back"))      return 4;
    if (!strcmp(slot, "tat_chest_l"))   return 5;
    if (!strcmp(slot, "tat_chest_r"))   return 6;
    if (!strcmp(slot, "tat_stomach"))   return 7;
    if (!strcmp(slot, "tat_low_back"))  return 8;
    return -1;
}

