/**
 * Membuka antarmuka Wardrobe Studio untuk pemain.
 * Mengubah skin ke CJ (model 0), melakukan broadcast state awal, dan memunculkan browser CEF.
 */
stock ShowPlayerWardrobe(playerid, const url[] = WARDROBE_URL, browserId = WARDROBE_BROWSER_ID)
{
    if (!IsPlayerConnected(playerid)) return 0;
    SetPlayerSkin(playerid, 0);

    if (strlen(g_PlayerWardrobe[playerid]) > 0)
    {
        new msg[256];
        format(msg, sizeof(msg), "%d save %s", playerid, g_PlayerWardrobe[playerid]);
        WR_BroadcastRPC(WARDROBE_RPC_ID, msg);
    }
    else
    {
        new msg[256];
        format(msg, sizeof(msg), "%d save none none none none none none none none none none none none none none none none 0.0 0.0 255 255 255", playerid);
        WR_BroadcastRPC(WARDROBE_RPC_ID, msg);
    }

    cef_create_browser(playerid, browserId, url, false, true);
    SendClientMessage(playerid, 0x38BDF8FF, "[WARDROBE] Membuka Wardrobe & Character Studio...");
    return 1;
}

/**
 * Menutup antarmuka Wardrobe Studio secara paksa.
 */
stock HidePlayerWardrobe(playerid, browserId = WARDROBE_BROWSER_ID)
{
    if (!IsPlayerConnected(playerid)) return 0;
    cef_focus_browser(playerid, browserId, false);
    cef_destroy_browser(playerid, browserId);
    return 1;
}

/**
 * Menyimpan dan menyiarkan payload 21-token ke seluruh pemain (misal saat load database).
 */
stock SetPlayerWardrobe(playerid, const payload[])
{
    if (!IsPlayerConnected(playerid)) return 0;
    format(g_PlayerWardrobe[playerid], sizeof(g_PlayerWardrobe[]), "%s", payload);
    new msg[256];
    format(msg, sizeof(msg), "%d save %s", playerid, payload);
    WR_BroadcastRPC(WARDROBE_RPC_ID, msg);
    return 1;
}

/**
 * Mengambil string 21-token pakaian aktif pemain.
 */
stock GetPlayerWardrobe(playerid, output[], maxlen = sizeof(output))
{
    if (!IsPlayerConnected(playerid)) return 0;
    format(output, maxlen, "%s", g_PlayerWardrobe[playerid]);
    return 1;
}

/**
 * Mereset pakaian pemain ke tubuh bersih tanpa aksesoris (bare body).
 */
stock ResetPlayerWardrobe(playerid)
{
    if (!IsPlayerConnected(playerid)) return 0;
