forward OnClothesReadyCEF(player_id, const arguments[]);
public OnClothesReadyCEF(player_id, const arguments[])
{
    printf("[Pawn.CEF] Player %d opened wardrobe (clothes:ready received)", player_id);
    if (strlen(g_PlayerWardrobe[player_id]) > 0)
    {
        new msg[256];
        format(msg, sizeof(msg), "%d save %s", player_id, g_PlayerWardrobe[player_id]);
        WR_BroadcastRPC(WARDROBE_RPC_ID, msg);

        new token[32];
        new skinR = 255, skinG = 255, skinB = 255, muscle = 500, fat = 200;
        new maskDff[32], maskTxd[32], headDff[32], headTxd[32], torsoDff[32], torsoTxd[32];
        new shoesDff[32], shoesTxd[32], legsDff[32], legsTxd[32], hatDff[32], hatTxd[32];
        new neckDff[32], neckTxd[32], watchDff[32], watchTxd[32];
        format(neckDff, sizeof(neckDff), "none");
        format(neckTxd, sizeof(neckTxd), "none");
        format(watchDff, sizeof(watchDff), "none");
        format(watchTxd, sizeof(watchTxd), "none");

        GetWardrobeToken(g_PlayerWardrobe[player_id], 0, maskDff, sizeof(maskDff));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 1, maskTxd, sizeof(maskTxd));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 2, headDff, sizeof(headDff));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 3, headTxd, sizeof(headTxd));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 4, torsoDff, sizeof(torsoDff));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 5, torsoTxd, sizeof(torsoTxd));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 6, shoesDff, sizeof(shoesDff));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 7, shoesTxd, sizeof(shoesTxd));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 8, legsDff, sizeof(legsDff));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 9, legsTxd, sizeof(legsTxd));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 10, hatDff, sizeof(hatDff));
        GetWardrobeToken(g_PlayerWardrobe[player_id], 11, hatTxd, sizeof(hatTxd));

        if (GetWardrobeToken(g_PlayerWardrobe[player_id], 20, token, sizeof(token)))
        {
            GetWardrobeToken(g_PlayerWardrobe[player_id], 12, neckDff, sizeof(neckDff));
            GetWardrobeToken(g_PlayerWardrobe[player_id], 13, neckTxd, sizeof(neckTxd));
            GetWardrobeToken(g_PlayerWardrobe[player_id], 14, watchDff, sizeof(watchDff));
            GetWardrobeToken(g_PlayerWardrobe[player_id], 15, watchTxd, sizeof(watchTxd));
            if (GetWardrobeToken(g_PlayerWardrobe[player_id], 16, token, sizeof(token))) muscle = strval(token);
            if (GetWardrobeToken(g_PlayerWardrobe[player_id], 17, token, sizeof(token))) fat = strval(token);
            if (GetWardrobeToken(g_PlayerWardrobe[player_id], 18, token, sizeof(token))) skinR = strval(token);
            if (GetWardrobeToken(g_PlayerWardrobe[player_id], 19, token, sizeof(token))) skinG = strval(token);
            if (GetWardrobeToken(g_PlayerWardrobe[player_id], 20, token, sizeof(token))) skinB = strval(token);
        }
        else
        {
            if (GetWardrobeToken(g_PlayerWardrobe[player_id], 12, token, sizeof(token))) muscle = strval(token);
            if (GetWardrobeToken(g_PlayerWardrobe[player_id], 13, token, sizeof(token))) fat = strval(token);
            if (GetWardrobeToken(g_PlayerWardrobe[player_id], 14, token, sizeof(token))) skinR = strval(token);
            if (GetWardrobeToken(g_PlayerWardrobe[player_id], 15, token, sizeof(token))) skinG = strval(token);
            if (GetWardrobeToken(g_PlayerWardrobe[player_id], 16, token, sizeof(token))) skinB = strval(token);
        }

        new json[1024], part[96];
        format(json, sizeof(json),
            "{\"skinColor\":{\"r\":%d,\"g\":%d,\"b\":%d},\"morphs\":{\"muscle\":%d,\"fat\":%d},\"equipped\":{",
            skinR, skinG, skinB, muscle, fat);
        format(part, sizeof(part), "\"mask\":{\"dff\":\"%s\",\"txd\":\"%s\"},", maskDff, maskTxd);
        strcat(json, part, sizeof(json));
        format(part, sizeof(part), "\"head\":{\"dff\":\"%s\",\"txd\":\"%s\"},", headDff, headTxd);
        strcat(json, part, sizeof(json));
        format(part, sizeof(part), "\"torso\":{\"dff\":\"%s\",\"txd\":\"%s\"},", torsoDff, torsoTxd);
        strcat(json, part, sizeof(json));
        format(part, sizeof(part), "\"shoes\":{\"dff\":\"%s\",\"txd\":\"%s\"},", shoesDff, shoesTxd);
        strcat(json, part, sizeof(json));
        format(part, sizeof(part), "\"legs\":{\"dff\":\"%s\",\"txd\":\"%s\"},", legsDff, legsTxd);
        strcat(json, part, sizeof(json));
        format(part, sizeof(part), "\"hat\":{\"dff\":\"%s\",\"txd\":\"%s\"},", hatDff, hatTxd);
        strcat(json, part, sizeof(json));
        format(part, sizeof(part), "\"necklace\":{\"dff\":\"%s\",\"txd\":\"%s\"},", neckDff, neckTxd);
        strcat(json, part, sizeof(json));
        format(part, sizeof(part), "\"watch\":{\"dff\":\"%s\",\"txd\":\"%s\"},", watchDff, watchTxd);
        strcat(json, part, sizeof(json));
        strcat(json, "\"tat_arm_l_top\":\"\",\"tat_arm_l_btm\":\"\",\"tat_arm_r_top\":\"\",\"tat_arm_r_btm\":\"\",", sizeof(json));
        strcat(json, "\"tat_back\":\"\",\"tat_chest_l\":\"\",\"tat_chest_r\":\"\",\"tat_stomach\":\"\",\"tat_low_back\":\"\"}}", sizeof(json));

        cef_emit_event(player_id, "clothes:initData", CEFSTR(json));
        printf("[Pawn.CEF] Seeded clothes:initData for player %d (skin=%d,%d,%d morph=%d,%d neck=%s watch=%s)", player_id, skinR, skinG, skinB, muscle, fat, neckTxd, watchTxd);
    }
    else
    {
        new msg[256];
        format(msg, sizeof(msg), "%d save none none none none none none none none none none none none none none none none 0.0 0.0 255 255 255", player_id);
        WR_BroadcastRPC(WARDROBE_RPC_ID, msg);
    }

    for (new i = 0; i < WARDROBE_MAX_TATTOOS; i++)
    {
        if (g_PlayerTattoo[player_id][i][0] != '\0')
        {
            new tatMsg[160];
            format(tatMsg, sizeof(tatMsg), "%d preview %s", player_id, g_PlayerTattoo[player_id][i]);
            WR_BroadcastRPC(WARDROBE_RPC_ID, tatMsg);
        }
    }
    return 1;
}

forward OnClothesPreviewCEF(player_id, const arguments[]);
public OnClothesPreviewCEF(player_id, const arguments[])
{
    new msg[160];
    format(msg, sizeof(msg), "%d preview %s", player_id, arguments);

    new slot[24];
    GetWardrobeToken(arguments, 0, slot, sizeof(slot));
    new idx = TattooSlotIndex(slot);
    if (idx >= 0)
    {
        new txd[32];
        GetWardrobeToken(arguments, 2, txd, sizeof(txd));
        if (!strcmp(txd, "none")) g_PlayerTattoo[player_id][idx][0] = '\0';
        else format(g_PlayerTattoo[player_id][idx], sizeof(g_PlayerTattoo[][]), "%s", arguments);
        WR_BroadcastRPC(WARDROBE_RPC_ID, msg);
    }
    else
    {
        WR_SendRPC(player_id, WARDROBE_RPC_ID, msg);
    }
    return 1;
}

