// 3. OnPlayerStreamIn Hook
public OnPlayerStreamIn(playerid, forplayerid)
{
    if (g_PlayerWardrobe[playerid][0] != '\0')
    {
        new msg[256];
        format(msg, sizeof(msg), "%d save %s", playerid, g_PlayerWardrobe[playerid]);
        WR_SendRPC(forplayerid, WARDROBE_RPC_ID, msg);
    }
    else if (GetPlayerSkin(playerid) == 0)
    {
        new msg[256];
        format(msg, sizeof(msg), "%d save none none none none none none none none none none none none none none none none 0.0 0.0 255 255 255", playerid);
        WR_SendRPC(forplayerid, WARDROBE_RPC_ID, msg);
    }

    if (g_PlayerWalkStyle[playerid][0] != '\0')
    {
        new msg[128];
        format(msg, sizeof(msg), "%d walkstyle %s", playerid, g_PlayerWalkStyle[playerid]);
        WR_SendRPC(forplayerid, WARDROBE_RPC_ID, msg);
    }

    for (new i = 0; i < WARDROBE_MAX_TATTOOS; i++)
    {
        if (g_PlayerTattoo[playerid][i][0] != '\0')
        {
            new msg[160];
            format(msg, sizeof(msg), "%d preview %s", playerid, g_PlayerTattoo[playerid][i]);
            WR_SendRPC(forplayerid, WARDROBE_RPC_ID, msg);
        }
    }

    #if defined WR_OnPlayerStreamIn
        return WR_OnPlayerStreamIn(playerid, forplayerid);
    #else
        return 1;
    #endif
}
